val isCourse = (entryKey as? BiliPaiNavKey.BangumiPlayer)?.isCourse ?: false
val seasonProgress = (entryKey as? BiliPaiNavKey.BangumiPlayer)?.resumePositionMs?.div(1000.0) ?: 0.0

        try {
