            }
        } catch (cancelled: CancellationException) { throw cancelled
        } catch (failure: Exception) { if (memory.isCurrentRequest()) { error = failure.message ?: "番剧播放失败"; loaded = false }
        } finally { if (memory.isCurrentRequest()) opening = false }
    }
