internal fun selectBangumi(info: BangumiVideoInfo, season: BangumiSeason, episode: BangumiEpisode, quality: Int): PlaybackSource {
    validateBangumiPlayableVideoInfo(info).getOrElse { throw BiliApiException(-403, it.message.orEmpty()) }
    val referer = if (season.isCourse) "https://www.bilibili.com/cheese/play/ep${episode.id}"
        else "https://www.bilibili.com/bangumi/play/ep${episode.id}"
    val title = "${season.title} · ${episode.title} ${episode.subtitle}".trim()
    info.dash?.let { dash ->
        val video = dash.getBestVideo(quality, preferCodec = "avc1", secondPreferCodec = "hev1", isHevcSupported = true, isAv1Supported = true)
        val url = video?.getValidUrl()?.let(::playableUrl)
        if (url != null) return PlaybackSource(url, dash.getBestAudio()?.getValidUrl()?.let(::playableUrl), title, referer, quality = video?.id ?: quality)
    }
    val segments = info.durl.orEmpty().ifEmpty { info.durls.orEmpty() }
    val urls = collectPlayableDurlUrls(segments)
    if (segments.isNotEmpty() && urls.size == segments.size && urls.all { playableUrl(it) != null }) {
        val parts = segments.zip(urls).map { (segment, url) -> PlaybackSegment(requireNotNull(playableUrl(url)),
            segment.length.takeIf { it > 0 }?.div(1000.0)) }
        return PlaybackSource(parts.first().url, null, title, referer, quality = info.quality,
            progressiveSegments = if (parts.size > 1) parts else emptyList())

fun stop() {
    val a=held() ?: return
    cancelCardResolution()
    checkpoint()
    a.native.current()?.let { expected -> a.native.admitPlaybackDispatch(expected) { a.section.nativePlayer.stopIfSourceVersion(expected.sourceVersion) } }
    lease=null;retireAssembly(a) // retire/cancel immediately; Root joins outside locks
    playlist.clearPlaylist()
}

override fun capturePlaybackDispatch(): DesktopOriginalVideoAcceptedPublication? {
    val expected = native.current() ?: return null
    return expected.takeIf { capture(it) != null }
}

internal fun currentSourceSnapshot(): OwnedPlaybackSourceSnapshot? = synchronized(lock) {
    if (closed.get()) null else requestedSource?.let { source ->
        OwnedPlaybackSourceSnapshot(sourceVersion, source.immutableSnapshot())
    }
}

/** The publication identity alone is insufficient for same-version recovery:
 * compare the complete immutable source while holding the native root lock. */
internal fun ownsSourceSnapshot(expected: OwnedPlaybackSourceSnapshot): Boolean = synchronized(lock) {
    !closed.get() && sourceVersion == expected.sourceVersion && requestedSource == expected.source
}

private fun load(source: PlaybackSource, preserveSubtitles: Boolean, startMuted: Boolean? = null) {
    synchronized(lock) {
        check(!closed.get()) { "Player is closed" }
        check(idleCacheMaintenance==null) { "播放器缓存正在清理，请稍后重试" }
        // Validate and freeze caller-owned maps before transferring media ownership.
        val retainedSource = source.immutableSnapshot()
        val previousTransport = requestedSource?.nativeTransport
        if (!preserveSubtitles) retainedSource.nativeTransport?.lease?.requireUnattached()
        if (!preserveSubtitles || previousTransport !== retainedSource.nativeTransport)
            previousTransport?.retire(sourceVersion, requestedSource?.nativePublication)
        if (!preserveSubtitles) {
            sourceVersion++; softwareDecodingRequested = false
            if (videoShaderSourceVersion != null) installVideoShaders(PreparedVideoShaders(emptyList(), emptySet()))
        }
        if (!preserveSubtitles) { externalSubtitles.clear(); subtitleControlVersion++ }
        requestedSource = retainedSource
        requestedLoadMute = startMuted
        val revision = ++playbackRevision

fun acquire(target: DesktopMediaPageMemory) {
    require(target in pages)
    pages.filter { it !== target }.forEach { it.stopPlayback() }
    onAcquire()
}

/** Always mounted by the shell; page disposal does not stop, detach ownership or close the live socket. */
@Composable
fun DesktopRetainedMediaEffects(memory: DesktopRetainedMedia, onActive: (Boolean) -> Unit) {
    val latestActive by rememberUpdatedState(onActive)
    val versions = memory.pages.map { it.sourceVersion to it.opening }
    LaunchedEffect(memory, versions) {
        val player = memory.player ?: return@LaunchedEffect
        var completedEpisode: Long? = null
        player.state.collect { state ->
            memory.pages.filter { it.sourceVersion != null && !it.ownsNativeSource }.forEach { it.stopPlayback() }
            val episodeVersion = memory.bangumi.sourceVersion
            if (memory.current === memory.bangumi && state.ended && episodeVersion != null && completedEpisode != episodeVersion) {
                completedEpisode = episodeVersion
                // Upstream BangumiPlayerViewModel always advances sequentially and stops at the last episode.
                memory.bangumi.next?.invoke() ?: run { memory.bangumi.notice = "已是最后一集" }
            }
            if (memory.current === memory.external && state.ended) memory.external.releaseCompletedLaunch()
            latestActive(memory.pages.any { it.opening } || memory.current != null && state.error == null && !state.ended &&
                (state.loading || state.videoCodec != null || state.audioCodec != null))
        }
